// Simple Orbit Escape game
// Canvas with id="game"
(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  const W = canvas.width = canvas.clientWidth || 800;
  const H = canvas.height = canvas.clientHeight || 600;

  // Ship state
  const ship = {
    x: W / 2,
    y: H * 0.8,
    angle: 0,
    radius: 10,
    thrust: 0,
    vx: 0,
    vy: 0,
    fuel: 100,
    shield: false,
  };

  const keys = {};
  addEventListener('keydown', e => (keys[e.code] = true));
  addEventListener('keyup', e => (keys[e.code] = false));

  // Asteroids & pickups
  const asteroids = [];
  const pickups = [];

  function spawnAsteroid() {
    const size = Math.random() * 30 + 15;
    asteroids.push({ x: Math.random() * W, y: -size, r: size, speed: 1 + Math.random() * 2 });
  }
  function spawnPickup() {
    const type = Math.random() < 0.5 ? 'fuel' : 'shield';
    pickups.push({ x: Math.random() * W, y: -20, r: 8, type, speed: 1.5 });
  }
  let spawnTimer = 0;

  function update(dt) {
    // Controls
    if (keys['ArrowLeft']) ship.angle -= 0.06 * dt;
    if (keys['ArrowRight']) ship.angle += 0.06 * dt;
    if (keys['ArrowUp'] && ship.fuel > 0) {
      ship.thrust = 0.1;
      ship.fuel -= 0.02 * dt;
    } else {
      ship.thrust = 0;
    }
    // Apply thrust
    ship.vx += Math.cos(ship.angle) * ship.thrust * dt;
    ship.vy += Math.sin(ship.angle) * ship.thrust * dt;
    // Simple drag
    ship.vx *= 0.99;
    ship.vy *= 0.99;
    ship.x += ship.vx * dt;
    ship.y += ship.vy * dt;
    // Keep on screen
    if (ship.x < 0) ship.x = W;
    if (ship.x > W) ship.x = 0;
    if (ship.y < 0) ship.y = H;
    if (ship.y > H) ship.y = H;

    // Spawn objects
    spawnTimer += dt;
    if (spawnTimer > 1500) {
      spawnAsteroid();
      if (Math.random() < 0.3) spawnPickup();
      spawnTimer = 0;
    }

    // Update asteroids
    for (let i = asteroids.length - 1; i >= 0; i--) {
      const a = asteroids[i];
      a.y += a.speed * dt;
      if (a.y - a.r > H) asteroids.splice(i, 1);
      // Collision
      const dx = a.x - ship.x, dy = a.y - ship.y;
      if (Math.hypot(dx, dy) < a.r + ship.radius) {
        if (ship.shield) { ship.shield = false; asteroids.splice(i, 1); }
        else { gameOver(); return; }
      }
    }
    // Update pickups
    for (let i = pickups.length - 1; i >= 0; i--) {
      const p = pickups[i];
      p.y += p.speed * dt;
      if (p.y - p.r > H) pickups.splice(i, 1);
      const dx = p.x - ship.x, dy = p.y - ship.y;
      if (Math.hypot(dx, dy) < p.r + ship.radius) {
        if (p.type === 'fuel') ship.fuel = Math.min(100, ship.fuel + 30);
        else ship.shield = true;
        pickups.splice(i, 1);
      }
    }
  }

  let last = performance.now();
  let running = true;
  function loop() {
    if (!running) return;
    const now = performance.now();
    const dt = now - last;
    last = now;
    update(dt);
    draw();
    requestAnimationFrame(loop);
  }

  function draw() {
    ctx.clearRect(0, 0, W, H);
    // Ship
    ctx.save();
    ctx.translate(ship.x, ship.y);
    ctx.rotate(ship.angle);
    ctx.beginPath();
    ctx.moveTo(15, 0);
    ctx.lineTo(-10, -8);
    ctx.lineTo(-10, 8);
    ctx.closePath();
    ctx.fillStyle = ship.shield ? 'cyan' : 'white';
    ctx.fill();
    ctx.restore();
    // Asteroids
    ctx.fillStyle = 'gray';
    asteroids.forEach(a => {
      ctx.beginPath();
      ctx.arc(a.x, a.y, a.r, 0, Math.PI * 2);
      ctx.fill();
    });
    // Pickups
    pickups.forEach(p => {
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2);
      ctx.fillStyle = p.type === 'fuel' ? 'lime' : 'orange';
      ctx.fill();
    });
    // HUD
    ctx.fillStyle = 'white';
    ctx.font = '14px sans-serif';
    ctx.fillText(`Fuel: ${Math.max(0, ship.fuel.toFixed(0))}`, 10, 20);
  }

  function gameOver() {
    running = false;
    ctx.fillStyle = 'red';
    ctx.font = '36px sans-serif';
    ctx.fillText('Game Over', W / 2 - 80, H / 2);
  }

  // Start loop
  requestAnimationFrame(loop);
})();
